    public static function findByCode(string $code): ?array
    {
        $all = static::getFullCatalog();
        foreach ($all as $spec => $group) {
            if (isset($group['procedures'][$code])) {
                return $group['procedures'][$code];
            }
        }
        return null;
    }

    public static function searchByName(string $keyword): array
    {
        $keyword = mb_strtolower(trim($keyword), 'UTF-8');
        $results = [];
        $all = static::getFullCatalog();
        foreach ($all as $spec => $group) {
            foreach ($group['procedures'] as $code => $proc) {
                if (str_contains(mb_strtolower($proc['name'], 'UTF-8'), $keyword) || str_contains(mb_strtolower($code, 'UTF-8'), $keyword)) {
                    $results[] = $proc;
                    if (count($results) >= 100) return $results;
                }
            }
        }
        return $results;
    }

    public static function getCountByClassification(): array
    {
        $counts = ['Đặc biệt' => 0, 'Loại I' => 0, 'Loại II' => 0, 'Loại III' => 0];
        $all = static::getFullCatalog();
        foreach ($all as $group) {
            foreach ($group['procedures'] as $proc) {
                $c = $proc['classification'] ?? 'Loại III';
                if (!isset($counts[$c])) $counts[$c] = 0;
                $counts[$c]++;
            }
        }
        return $counts;
    }

    public static function getTotalProceduresCount(): int
    {
        $total = 0;
        $all = static::getFullCatalog();
        foreach ($all as $group) {
            $total += count($group['procedures']);
        }
        return $total;
    }
}